arguments.command:
cd /tmp/sv-682c3afb47824fc78db38f594d6359a7/symbols && \
# Check debuglink target
readelf -p .gnu_debuglink libmonosgen-2.0.so 2>/dev/null | head -5; \
echo "---"; \
# Try dynamic symbols for the offsets
# Frame #01: 0x222098, #02: 0x222234, #03: 0x19bac0, #06: 0x19bc14
nm -D libmonosgen-2.0.so 2>/dev/null | sort | head -3; \
echo "--- Using nm -D to find nearest symbols ---"; \
for addr in 0x222098 0x222234 0x19bac0 0x19bc14; do
  # Find the nearest symbol at or before this address
  nearest=$(nm -D libmonosgen-2.0.so 2>/dev/null | sort | awk -v target="$addr" '
    BEGIN { best_name="??"; best_addr="0"; target_dec=strtonum(target) }
    /^[0-9a-f]+ [TtWw]/ { 
      addr_dec=strtonum("0x"$1); 
      if (addr_dec <= target_dec && addr_dec > strtonum("0x"best_addr)) { 
        best_addr=$1; best_name=$3 
      } 
    }
    END { printf "%s+0x%x", best_name, target_dec - strtonum("0x"best_addr) }
  ')
  echo "  $addr -> $nearest"
done

