arguments.command:
cd /tmp/sv-682c3afb47824fc78db38f594d6359a7/symbols && \
# Use readelf to get all defined FUNC symbols with sizes, sorted by address
readelf --syms -W libmonosgen-2.0.so 2>/dev/null | \
  awk '$4 == "FUNC" && $7 != "UND" { printf "%s %s %s\n", $2, $3, $8 }' | \
  sort > /tmp/mono_funcs.txt && \
echo "Total defined functions: $(wc -l < /tmp/mono_funcs.txt)" && \
echo "---" && \
# Now resolve each address
for addr_hex in 222098 222234 19bac0 19bc14; do
  addr_dec=$((16#$addr_hex))
  result=$(awk -v target="$addr_dec" '
    BEGIN { best_name="??"; best_off=target; }
    {
      addr=strtonum("0x"$1);
      size=strtonum("0x"$2);
      if (addr <= target && (addr + size) > target) {
        printf "%s+0x%x (size=0x%s)\n", $3, target - addr, $2;
        found=1;
        exit;
      }
      if (addr <= target && (target - addr) < best_off) {
        best_off = target - addr;
        best_name = $3;
      }
    }
    END { if (!found) printf "%s+0x%x (nearest, no exact match)\n", best_name, best_off; }
  ' /tmp/mono_funcs.txt)
  echo "  #pc 0x$addr_hex -> $result"
done

