arguments.command:
cd /tmp/sv-682c3afb47824fc78db38f594d6359a7/symbols && \
# Use .eh_frame_hdr table to find exact function boundaries
# This gives us the FDE table - each entry maps to a function
readelf --debug-dump=frames libmonosgen-2.0.so 2>/dev/null | \
  grep -E 'pc=' | \
  awk -F'[=.]' '{ print $2 }' | \
  sort -u > /tmp/eh_starts.txt
echo "Total FDE entries: $(wc -l < /tmp/eh_starts.txt)"

# Now find the FDE that contains each of our addresses
for addr_hex in 222098 222234 19bac0 19bc14; do
  echo "=== 0x$addr_hex ==="
  readelf --debug-dump=frames libmonosgen-2.0.so 2>/dev/null | \
    grep "pc=" | \
    awk -v target="0x$addr_hex" '{
      # Extract start..end range
      match($0, /pc=([0-9a-f]+)\.\.([0-9a-f]+)/, arr);
      if (arr[1] != "" && arr[2] != "") {
        start = strtonum("0x" arr[1]);
        end = strtonum("0x" arr[2]);
        t = strtonum(target);
        if (t >= start && t < end) {
          printf "  FDE range: 0x%s..0x%s (offset +0x%x)\n", arr[1], arr[2], t - start;
        }
      }
    }'
done

